db AS (SELECT sr.* FROM survey_response sr JOIN survey s ON s.id = sr."surveyId" WHERE s."alchemerId"::text = '90558103')
SELECT count(*)                                                                    AS bi_responses,
       count(db.id)                                                                AS found_in_db,
       count(db.id) FILTER (WHERE db.visit_msg_id IS NOT NULL AND db."NPS_SCORE" BETWEEN 0 AND 10) AS shown_in_dashboards,
       count(*) FILTER (WHERE db.id IS NULL)                                       AS not_found,
       count(db.id) FILTER (WHERE db.visit_msg_id IS NULL)                         AS found_not_linked,
       count(db.id) FILTER (WHERE round(db."NPS_SCORE") <> bi.score)               AS score_mismatch,
       count(db.id) FILTER (WHERE db.status <> bi.status)                          AS status_mismatch,
       count(db.id) FILTER (WHERE coalesce(db.sguid, '') <> bi.sguid)             AS sguid_mismatch,
       count(db.id) FILTER (WHERE bi.sguid ~ '^[0-9]+$' AND db.visit_msg_id IS NOT NULL) AS legacy_shown,     -- expect 480
       count(db.id) FILTER (WHERE bi.sguid !~ '^[0-9]+$' AND db.visit_msg_id IS NOT NULL) AS platform_shown    -- expect 383 (prod)
FROM bi LEFT JOIN db ON db."alchemerResponseId" = bi.rid;

