a8d1c5ef934')
),
db AS (SELECT sr.* FROM survey_response sr JOIN survey s ON s.id = sr."surveyId" WHERE s."alchemerId"::text = '90558103')
SELECT bi.rid AS alchemer_response_id, bi.status AS bi_status, bi.score AS bi_score,
       CASE WHEN bi.sguid ~ '^[0-9]+$' THEN 'legacy' ELSE 'platform' END AS kind,
       CASE WHEN db.id IS NULL THEN 'not in DB (not synced to this copy yet)'
            WHEN db.visit_msg_id IS NULL THEN 'in DB but not linked to a Visit Msg'
            ELSE 'linked but score outside 0-10' END AS reason,
       (db."dateStarted" AT TIME ZONE 'Europe/Zagreb')::timestamp(0) AS db_started_local
FROM bi LEFT JOIN db ON db."alchemerResponseId" = bi.rid
WHERE db.id IS NULL OR db.visit_msg_id IS NULL OR NOT (db."NPS_SCORE" BETWEEN 0 AND 10)
ORDER BY bi.rid::int;

