db AS (SELECT sr.* FROM survey_response sr JOIN survey s ON s.id = sr."surveyId" WHERE s."alchemerId"::text = '90558103')
SELECT db."alchemerResponseId" AS alchemer_response_id, db.status, round(db."NPS_SCORE") AS score, db.sguid,
       (db."dateStarted" AT TIME ZONE 'Europe/Zagreb')::timestamp(0) AS started_local,
       (db.visit_msg_id IS NOT NULL) AS shown_in_dashboards
FROM db WHERE db."alchemerResponseId" NOT IN (SELECT rid FROM bi)
ORDER BY db."dateStarted";

-- 4) NPS as the dashboards compute it, split like the reference above (compare with the BI numbers in the header)
SELECT CASE WHEN sr."dateStarted" < ('2024-10-16 00:00'::timestamp AT TIME ZONE 'Europe/Zagreb') THEN 'legacy (before 16 Oct 2024)'
            ELSE 'platform (from 16 Oct 2024)' END AS period,
       count(*) AS responses,
       count(*) FILTER (WHERE round(sr."NPS_SCORE") >= 9) AS promoters,
       count(*) FILTER (WHERE round(sr."NPS_SCORE") <= 6) AS detractors,
       floor(1000.0 * (count(*) FILTER (WHERE round(sr."NPS_SCORE") >= 9)
                     - count(*) FILTER (WHERE round(sr."NPS_SCORE") <= 6)) / count(*) + 0.5) / 10 AS nps
FROM survey_response sr
JOIN survey s     ON s.id = sr."surveyId" AND s."alchemerId"::text = '90558103'
JOIN visit_msg vm ON vm.id = sr.visit_msg_id
WHERE sr."NPS_SCORE" BETWEEN 0 AND 10
  AND sr."dateStarted" < ('2026-10-21 14:31'::timestamp AT TIME ZONE 'Europe/Zagreb')   -- same cut-off as the BI export
GROUP BY 1 ORDER BY 1;
